export const PORTAL_V6_SQL = "-- YTÜ CORE Portal V6 governance / control-plane additions\n-- Additive only. Existing V1-V5 data and role values remain valid.\n\nCREATE TABLE IF NOT EXISTS portal_teams (\n  code TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  domain TEXT NOT NULL DEFAULT '',\n  description TEXT NOT NULL DEFAULT '',\n  visibility TEXT NOT NULL DEFAULT 'restricted'\n    CHECK (visibility IN ('restricted','members')),\n  status TEXT NOT NULL DEFAULT 'active'\n    CHECK (status IN ('active','archived')),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS portal_team_memberships (\n  team_code TEXT NOT NULL,\n  member_id TEXT NOT NULL,\n  team_role TEXT NOT NULL DEFAULT 'engineer'\n    CHECK (team_role IN ('owner','captain','lead','engineer','contributor','observer')),\n  status TEXT NOT NULL DEFAULT 'active'\n    CHECK (status IN ('active','inactive')),\n  capabilities_json TEXT NOT NULL DEFAULT '[]',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (team_code, member_id),\n  FOREIGN KEY (team_code) REFERENCES portal_teams(code) ON DELETE CASCADE,\n  FOREIGN KEY (member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_role_profiles (\n  role_key TEXT PRIMARY KEY,\n  label TEXT NOT NULL,\n  scope TEXT NOT NULL DEFAULT 'global',\n  description TEXT NOT NULL DEFAULT '',\n  capabilities_json TEXT NOT NULL DEFAULT '[]',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS portal_member_capabilities (\n  member_id TEXT NOT NULL,\n  capability TEXT NOT NULL,\n  granted_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (member_id, capability),\n  FOREIGN KEY (member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_project_registry (\n  slug TEXT PRIMARY KEY,\n  title TEXT NOT NULL,\n  summary TEXT NOT NULL DEFAULT '',\n  domain TEXT NOT NULL DEFAULT '',\n  team_code TEXT,\n  status TEXT NOT NULL DEFAULT 'concept'\n    CHECK (status IN ('concept','design','prototype','testing','operational','paused','archived')),\n  visibility TEXT NOT NULL DEFAULT 'team'\n    CHECK (visibility IN ('team','members','leads','admins')),\n  owner_member_id TEXT,\n  start_at TEXT,\n  target_at TEXT,\n  risk_level TEXT NOT NULL DEFAULT 'medium'\n    CHECK (risk_level IN ('low','medium','high','critical')),\n  readiness INTEGER NOT NULL DEFAULT 0\n    CHECK (readiness BETWEEN 0 AND 100),\n  metadata_json TEXT NOT NULL DEFAULT '{}',\n  created_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (team_code) REFERENCES portal_teams(code) ON DELETE SET NULL,\n  FOREIGN KEY (owner_member_id) REFERENCES portal_members(id) ON DELETE SET NULL\n);\n\nCREATE TABLE IF NOT EXISTS portal_project_map_edges (\n  id TEXT PRIMARY KEY,\n  source_type TEXT NOT NULL\n    CHECK (source_type IN ('project','team','vehicle','repo','vault','task')),\n  source_ref TEXT NOT NULL,\n  target_type TEXT NOT NULL\n    CHECK (target_type IN ('project','team','vehicle','repo','vault','task')),\n  target_ref TEXT NOT NULL,\n  relation TEXT NOT NULL DEFAULT 'depends_on',\n  label TEXT NOT NULL DEFAULT '',\n  created_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(source_type, source_ref, target_type, target_ref, relation)\n);\n\nCREATE TABLE IF NOT EXISTS portal_vehicle_profiles (\n  vehicle_id TEXT PRIMARY KEY,\n  team_code TEXT,\n  project_slug TEXT,\n  platform_type TEXT NOT NULL DEFAULT 'vehicle',\n  lifecycle TEXT NOT NULL DEFAULT 'prototype'\n    CHECK (lifecycle IN ('concept','prototype','testing','operational','maintenance','retired')),\n  serial_number TEXT NOT NULL DEFAULT '',\n  criticality TEXT NOT NULL DEFAULT 'medium'\n    CHECK (criticality IN ('low','medium','high','critical')),\n  description TEXT NOT NULL DEFAULT '',\n  owner_member_id TEXT,\n  metadata_json TEXT NOT NULL DEFAULT '{}',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (vehicle_id) REFERENCES portal_vehicle_units(id) ON DELETE CASCADE,\n  FOREIGN KEY (team_code) REFERENCES portal_teams(code) ON DELETE SET NULL,\n  FOREIGN KEY (project_slug) REFERENCES portal_project_registry(slug) ON DELETE SET NULL,\n  FOREIGN KEY (owner_member_id) REFERENCES portal_members(id) ON DELETE SET NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_team_memberships_member\n  ON portal_team_memberships(member_id, status);\nCREATE INDEX IF NOT EXISTS idx_team_memberships_team\n  ON portal_team_memberships(team_code, status);\nCREATE INDEX IF NOT EXISTS idx_member_capabilities_member\n  ON portal_member_capabilities(member_id);\nCREATE INDEX IF NOT EXISTS idx_project_registry_team\n  ON portal_project_registry(team_code, status, updated_at);\nCREATE INDEX IF NOT EXISTS idx_project_map_source\n  ON portal_project_map_edges(source_type, source_ref);\nCREATE INDEX IF NOT EXISTS idx_project_map_target\n  ON portal_project_map_edges(target_type, target_ref);\nCREATE INDEX IF NOT EXISTS idx_vehicle_profiles_team\n  ON portal_vehicle_profiles(team_code, lifecycle);\n\nINSERT OR IGNORE INTO portal_teams (code,name,domain,description,visibility) VALUES\n('MAR','CORE Marine','USV / surface autonomy','İnsansız suüstü araçları, seyrüsefer ve deniz saha operasyonları.','restricted'),\n('SUB','CORE Subsea','AUV / ROV','Sualtı araçları, underwater perception ve test operasyonları.','restricted'),\n('LAND','CORE Land','UGV / rover','Kara robotları, rover ve otonom mobil platformlar.','restricted'),\n('AIR','CORE Air','UAV','İnsansız hava araçları, avionics ve uçuş sistemleri.','restricted'),\n('IND','CORE Industrial','AMR / work machine','Endüstriyel mobil robotlar, tarım ve maden uygulamaları.','restricted'),\n('SPACE','CORE Space','CubeSat / payload','Uydu, yer istasyonu, faydalı yük ve uzay sistemleri.','restricted'),\n('ROCKET','CORE Rocket','high altitude / propulsion','Roket, itki, yüksek irtifa ve uçuş sistemleri.','restricted'),\n('SYS','CORE Systems','runtime / autonomy','Ortak runtime, otonomi, karar ve sistem mimarisi.','restricted'),\n('EMB','CORE Embedded','PCB / MCU / power','Gömülü yazılım, PCB, MCU, güç ve elektronik platformlar.','restricted'),\n('OPS','CORE Ops','ground / telemetry / field','Yer istasyonu, telemetri, saha ve operasyon koordinasyonu.','restricted'),\n('RES','CORE Research','research / patents','Araştırma, rapor, yayın, patent ve ön tasarım.','restricted');\n\nINSERT OR IGNORE INTO portal_role_profiles (role_key,label,scope,description,capabilities_json) VALUES\n('admin','Portal Yöneticisi','global','Tüm portal, erişim ve kontrol-plane yetkileri.','[\"portal.admin\",\"teams.read_all\",\"teams.manage\",\"roles.manage\",\"control.projects\",\"control.vehicles\",\"project.map.edit\",\"vault.approve\",\"ops.read_all\"]'),\n('lead','Takım / Program Lideri','global','Proje, araç ve teknik yönetim yetkileri; takım görünürlüğü üyelikle sınırlıdır.','[\"control.projects\",\"control.vehicles\",\"project.map.edit\",\"vault.approve\"]'),\n('member','Mühendis / Üye','global','Günlük mühendislik çalışma alanı ve takım üyeliği kapsamındaki erişim.','[]'),\n('alumni','Mezun','global','Kısıtlı kurumsal hafıza ve davet edilen takım alanı erişimi.','[]'),\n('viewer','Görüntüleyici','global','Salt okunur, açıkça izin verilen alanlar.','[]'),\n('team_owner','Takım Sahibi','team','Takım sayfası, üyelik, proje ve araç yönetimi.','[\"team.manage\",\"team.project.manage\",\"team.vehicle.manage\"]'),\n('team_captain','Kaptan','team','Takım operasyonu ve proje/araç koordinasyonu.','[\"team.project.manage\",\"team.vehicle.manage\"]'),\n('team_lead','Takım Lideri','team','Teknik liderlik ve takım iş yönetimi.','[\"team.project.manage\"]'),\n('engineer','Mühendis','team','Takım çalışma alanı ve teknik veri erişimi.','[]'),\n('contributor','Katkıcı','team','Sınırlı takım çalışma alanı erişimi.','[]'),\n('observer','Gözlemci','team','Salt okunur takım görünürlüğü.','[]');\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_control_plane_schema',\n  '{\"version\":\"2026.09-v6\",\"features\":[\"team-workspaces\",\"team-memberships\",\"role-profiles\",\"member-capabilities\",\"internal-project-registry\",\"project-mapping\",\"vehicle-profiles\",\"control-plane\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0007_repo_review.sql
export const PORTAL_V7_SQL = "-- YTÜ CORE Portal RP-02 repository code review\n-- Additive only. Review state is portal governance metadata; Git objects remain in CORE Repo Service.\n\nCREATE TABLE IF NOT EXISTS portal_repo_reviews (\n  id TEXT PRIMARY KEY,\n  repository_id TEXT NOT NULL,\n  base_ref TEXT NOT NULL,\n  head_ref TEXT NOT NULL,\n  base_sha TEXT NOT NULL,\n  head_sha TEXT NOT NULL,\n  title TEXT NOT NULL DEFAULT '',\n  status TEXT NOT NULL DEFAULT 'open'\n    CHECK (status IN ('open','approved','changes_requested','closed')),\n  created_by_member_id TEXT NOT NULL,\n  created_by_email TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(repository_id, base_sha, head_sha),\n  FOREIGN KEY (repository_id) REFERENCES portal_native_repositories(id) ON DELETE CASCADE,\n  FOREIGN KEY (created_by_member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_repo_review_threads (\n  id TEXT PRIMARY KEY,\n  review_id TEXT NOT NULL,\n  file_path TEXT NOT NULL,\n  side TEXT NOT NULL DEFAULT 'head'\n    CHECK (side IN ('base','head')),\n  line_number INTEGER NOT NULL CHECK (line_number > 0),\n  line_sha TEXT,\n  created_by_member_id TEXT NOT NULL,\n  resolved_at TEXT,\n  resolved_by_member_id TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (review_id) REFERENCES portal_repo_reviews(id) ON DELETE CASCADE,\n  FOREIGN KEY (created_by_member_id) REFERENCES portal_members(id) ON DELETE CASCADE,\n  FOREIGN KEY (resolved_by_member_id) REFERENCES portal_members(id) ON DELETE SET NULL\n);\n\nCREATE TABLE IF NOT EXISTS portal_repo_review_comments (\n  id TEXT PRIMARY KEY,\n  thread_id TEXT NOT NULL,\n  author_member_id TEXT NOT NULL,\n  body TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  edited_at TEXT,\n  FOREIGN KEY (thread_id) REFERENCES portal_repo_review_threads(id) ON DELETE CASCADE,\n  FOREIGN KEY (author_member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_repo_review_submissions (\n  id TEXT PRIMARY KEY,\n  review_id TEXT NOT NULL,\n  reviewer_member_id TEXT NOT NULL,\n  outcome TEXT NOT NULL\n    CHECK (outcome IN ('comment','approve','request_changes')),\n  body TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (review_id) REFERENCES portal_repo_reviews(id) ON DELETE CASCADE,\n  FOREIGN KEY (reviewer_member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_repo_reviews_repository\n  ON portal_repo_reviews(repository_id, updated_at DESC);\nCREATE INDEX IF NOT EXISTS idx_repo_reviews_snapshot\n  ON portal_repo_reviews(repository_id, base_sha, head_sha);\nCREATE INDEX IF NOT EXISTS idx_repo_review_threads_review\n  ON portal_repo_review_threads(review_id, file_path, line_number);\nCREATE INDEX IF NOT EXISTS idx_repo_review_comments_thread\n  ON portal_repo_review_comments(thread_id, created_at);\nCREATE INDEX IF NOT EXISTS idx_repo_review_submissions_review\n  ON portal_repo_review_submissions(review_id, created_at DESC);\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_repo_review_schema',\n  '{\"version\":\"2026.09-rp02\",\"features\":[\"immutable-review-snapshots\",\"diff-hunks\",\"line-threads\",\"resolve-reopen\",\"review-submissions\",\"approve-request-changes\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0008_code_lab.sql
export const PORTAL_V8_SQL = "-- YTÜ CORE Portal CL-01 Code Lab execution metadata\n-- Additive only. User code executes in CORE Runner sandbox containers, never in the CMS Worker.\n\nCREATE TABLE IF NOT EXISTS portal_code_run_execution (\n  run_id TEXT PRIMARY KEY,\n  native_repository_id TEXT NOT NULL,\n  service_repository_id TEXT NOT NULL,\n  snapshot_ref TEXT NOT NULL,\n  snapshot_sha TEXT,\n  workflow_instance_id TEXT,\n  dispatch_token TEXT NOT NULL,\n  attempt INTEGER NOT NULL DEFAULT 1,\n  retry_of_run_id TEXT,\n  cancel_requested_at TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (run_id) REFERENCES portal_code_runs(id) ON DELETE CASCADE,\n  FOREIGN KEY (native_repository_id) REFERENCES portal_native_repositories(id) ON DELETE CASCADE,\n  FOREIGN KEY (retry_of_run_id) REFERENCES portal_code_runs(id) ON DELETE SET NULL\n);\n\nCREATE TABLE IF NOT EXISTS portal_code_run_events (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  run_id TEXT NOT NULL,\n  phase TEXT NOT NULL,\n  level TEXT NOT NULL DEFAULT 'info'\n    CHECK (level IN ('info','success','warning','error')),\n  message TEXT NOT NULL DEFAULT '',\n  metadata_json TEXT NOT NULL DEFAULT '{}',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (run_id) REFERENCES portal_code_runs(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_code_run_artifacts (\n  id TEXT PRIMARY KEY,\n  run_id TEXT NOT NULL,\n  name TEXT NOT NULL,\n  kind TEXT NOT NULL DEFAULT 'artifact',\n  mime_type TEXT NOT NULL DEFAULT 'application/octet-stream',\n  object_key TEXT NOT NULL UNIQUE,\n  size_bytes INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (run_id) REFERENCES portal_code_runs(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_code_run_execution_repo\n  ON portal_code_run_execution(native_repository_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_code_run_events_run\n  ON portal_code_run_events(run_id, created_at);\nCREATE INDEX IF NOT EXISTS idx_code_run_artifacts_run\n  ON portal_code_run_artifacts(run_id, created_at);\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_code_lab_schema',\n  '{\"version\":\"2026.09-cl01\",\"features\":[\"runner-workflow\",\"sandbox-container\",\"immutable-snapshot\",\"events\",\"logs\",\"artifacts\",\"cancel\",\"retry\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0009_code_terminal.sql
export const PORTAL_V9_SQL = "-- YTÜ CORE Portal CL-02 Live Terminal sessions\n-- Ephemeral interactive shells execute only inside CORE Runner containers.\n\nCREATE TABLE IF NOT EXISTS portal_code_terminal_sessions (\n  id TEXT PRIMARY KEY,\n  member_id TEXT NOT NULL,\n  native_repository_id TEXT NOT NULL,\n  service_repository_id TEXT NOT NULL,\n  repository_slug TEXT NOT NULL,\n  snapshot_ref TEXT NOT NULL,\n  snapshot_sha TEXT,\n  connect_token TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'preparing'\n    CHECK (status IN ('preparing','ready','connected','closed','expired','failed')),\n  expires_at TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  connected_at TEXT,\n  ended_at TEXT,\n  last_activity_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (member_id) REFERENCES portal_members(id) ON DELETE CASCADE,\n  FOREIGN KEY (native_repository_id) REFERENCES portal_native_repositories(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_code_terminal_member\n  ON portal_code_terminal_sessions(member_id, created_at DESC);\n\nCREATE INDEX IF NOT EXISTS idx_code_terminal_expiry\n  ON portal_code_terminal_sessions(status, expires_at);\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_code_terminal_schema',\n  '{\"version\":\"2026.09-cl02\",\"features\":[\"live-terminal\",\"websocket-stdin\",\"streaming-stdout\",\"ephemeral-workspace\",\"terminal-signal\",\"terminal-expiry\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0010_vault_upload_sessions.sql
export const PORTAL_V10_SQL = "-- YTÜ CORE Portal V12 Vault raw upload sessions\n-- Files are uploaded as raw request bodies to R2, then finalized into Vault metadata.\n\nCREATE TABLE IF NOT EXISTS portal_vault_upload_sessions (\n  id TEXT PRIMARY KEY,\n  member_id TEXT NOT NULL,\n  actor_email TEXT NOT NULL,\n  mode TEXT NOT NULL DEFAULT 'new'\n    CHECK (mode IN ('new','revision')),\n  target_file_id TEXT,\n  file_id TEXT NOT NULL,\n  revision INTEGER NOT NULL,\n  original_name TEXT NOT NULL,\n  mime_type TEXT NOT NULL DEFAULT 'application/octet-stream',\n  expected_size INTEGER NOT NULL,\n  actual_size INTEGER,\n  checksum_sha256 TEXT,\n  object_key TEXT NOT NULL UNIQUE,\n  capability_token TEXT NOT NULL,\n  metadata_json TEXT NOT NULL DEFAULT '{}',\n  status TEXT NOT NULL DEFAULT 'initiated'\n    CHECK (status IN ('initiated','uploaded','completed','failed','expired')),\n  expires_at TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  completed_at TEXT,\n  FOREIGN KEY (member_id) REFERENCES portal_members(id) ON DELETE CASCADE,\n  FOREIGN KEY (target_file_id) REFERENCES portal_vault_files(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_vault_upload_member\n  ON portal_vault_upload_sessions(member_id, created_at DESC);\n\nCREATE INDEX IF NOT EXISTS idx_vault_upload_status\n  ON portal_vault_upload_sessions(status, expires_at);\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_vault_upload_schema',\n  '{\"version\":\"2026.09-va02\",\"features\":[\"upload-session\",\"raw-put\",\"r2-direct-binding\",\"finalize-metadata\",\"revision-session\",\"upload-progress\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0011_mail_workspace.sql
export const PORTAL_V11_SQL = "-- CORE Mail Workspace V2\n-- Private/internal distribution groups and access-code protected groups.\n\nCREATE TABLE IF NOT EXISTS portal_mail_groups (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  description TEXT NOT NULL DEFAULT '',\n  owner_id TEXT NOT NULL,\n  access_mode TEXT NOT NULL DEFAULT 'private'\n    CHECK (access_mode IN ('private','locked')),\n  access_code_salt TEXT,\n  access_code_hash TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (owner_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_mail_group_members (\n  group_id TEXT NOT NULL,\n  member_id TEXT NOT NULL,\n  member_role TEXT NOT NULL DEFAULT 'member'\n    CHECK (member_role IN ('owner','member')),\n  added_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (group_id, member_id),\n  FOREIGN KEY (group_id) REFERENCES portal_mail_groups(id) ON DELETE CASCADE,\n  FOREIGN KEY (member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_mail_thread_groups (\n  thread_id TEXT NOT NULL,\n  group_id TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (thread_id, group_id),\n  FOREIGN KEY (thread_id) REFERENCES portal_mail_threads(id) ON DELETE CASCADE,\n  FOREIGN KEY (group_id) REFERENCES portal_mail_groups(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_portal_mail_group_member\n  ON portal_mail_group_members(member_id, group_id);\n\nCREATE INDEX IF NOT EXISTS idx_portal_mail_group_mode\n  ON portal_mail_groups(access_mode, updated_at);\n\nCREATE INDEX IF NOT EXISTS idx_portal_mail_thread_group\n  ON portal_mail_thread_groups(group_id, thread_id);\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_mail_schema',\n  '{\"version\":\"2026.09-mail-v2\",\"features\":[\"distribution-groups\",\"locked-groups\",\"integrated-reader\",\"viewport-mail\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0012_collaboration_finance.sql
export const PORTAL_V12_SQL = "-- CORE Portal V12 Collaboration & Finance\n-- Meetings, polls, reports and team budget ledger.\n\nCREATE TABLE IF NOT EXISTS portal_meeting_spaces (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  description TEXT NOT NULL DEFAULT '',\n  team_code TEXT,\n  project_slug TEXT,\n  visibility TEXT NOT NULL DEFAULT 'members'\n    CHECK (visibility IN ('private','team','members')),\n  created_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (created_by) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_meetings (\n  id TEXT PRIMARY KEY,\n  space_id TEXT,\n  calendar_event_id TEXT,\n  title TEXT NOT NULL,\n  agenda TEXT NOT NULL DEFAULT '',\n  starts_at TEXT NOT NULL,\n  ends_at TEXT,\n  team_code TEXT,\n  project_slug TEXT,\n  status TEXT NOT NULL DEFAULT 'scheduled'\n    CHECK (status IN ('scheduled','live','completed','cancelled')),\n  transport_mode TEXT NOT NULL DEFAULT 'audio_video'\n    CHECK (transport_mode IN ('audio_video','audio','external','none')),\n  transport_room TEXT NOT NULL,\n  created_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (space_id) REFERENCES portal_meeting_spaces(id) ON DELETE SET NULL,\n  FOREIGN KEY (calendar_event_id) REFERENCES portal_calendar_events(id) ON DELETE SET NULL,\n  FOREIGN KEY (created_by) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_meeting_participants (\n  meeting_id TEXT NOT NULL,\n  member_id TEXT NOT NULL,\n  participant_role TEXT NOT NULL DEFAULT 'participant'\n    CHECK (participant_role IN ('host','moderator','participant')),\n  invite_state TEXT NOT NULL DEFAULT 'invited'\n    CHECK (invite_state IN ('invited','accepted','declined','attended')),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (meeting_id,member_id),\n  FOREIGN KEY (meeting_id) REFERENCES portal_meetings(id) ON DELETE CASCADE,\n  FOREIGN KEY (member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_meeting_notes (\n  id TEXT PRIMARY KEY,\n  meeting_id TEXT NOT NULL,\n  author_id TEXT NOT NULL,\n  kind TEXT NOT NULL DEFAULT 'note'\n    CHECK (kind IN ('note','decision','action','transcript')),\n  body TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (meeting_id) REFERENCES portal_meetings(id) ON DELETE CASCADE,\n  FOREIGN KEY (author_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_meeting_reports (\n  meeting_id TEXT PRIMARY KEY,\n  summary TEXT NOT NULL,\n  resource_id TEXT,\n  generated_by TEXT NOT NULL,\n  generated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (meeting_id) REFERENCES portal_meetings(id) ON DELETE CASCADE,\n  FOREIGN KEY (resource_id) REFERENCES portal_resources(id) ON DELETE SET NULL,\n  FOREIGN KEY (generated_by) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_polls (\n  id TEXT PRIMARY KEY,\n  meeting_id TEXT,\n  title TEXT NOT NULL,\n  description TEXT NOT NULL DEFAULT '',\n  scope TEXT NOT NULL DEFAULT 'global'\n    CHECK (scope IN ('global','team','meeting')),\n  team_code TEXT,\n  status TEXT NOT NULL DEFAULT 'open'\n    CHECK (status IN ('open','closed')),\n  closes_at TEXT,\n  created_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (meeting_id) REFERENCES portal_meetings(id) ON DELETE CASCADE,\n  FOREIGN KEY (created_by) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_poll_options (\n  id TEXT PRIMARY KEY,\n  poll_id TEXT NOT NULL,\n  label TEXT NOT NULL,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  FOREIGN KEY (poll_id) REFERENCES portal_polls(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_poll_votes (\n  poll_id TEXT NOT NULL,\n  option_id TEXT NOT NULL,\n  member_id TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (poll_id,member_id),\n  FOREIGN KEY (poll_id) REFERENCES portal_polls(id) ON DELETE CASCADE,\n  FOREIGN KEY (option_id) REFERENCES portal_poll_options(id) ON DELETE CASCADE,\n  FOREIGN KEY (member_id) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_budget_accounts (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  team_code TEXT,\n  project_slug TEXT,\n  currency TEXT NOT NULL DEFAULT 'TRY',\n  opening_balance_minor INTEGER NOT NULL DEFAULT 0,\n  status TEXT NOT NULL DEFAULT 'active'\n    CHECK (status IN ('active','closed')),\n  owner_member_id TEXT,\n  created_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (owner_member_id) REFERENCES portal_members(id) ON DELETE SET NULL,\n  FOREIGN KEY (created_by) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_budget_allocations (\n  id TEXT PRIMARY KEY,\n  account_id TEXT NOT NULL,\n  category TEXT NOT NULL,\n  amount_minor INTEGER NOT NULL,\n  period_start TEXT,\n  period_end TEXT,\n  notes TEXT NOT NULL DEFAULT '',\n  created_by TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (account_id) REFERENCES portal_budget_accounts(id) ON DELETE CASCADE,\n  FOREIGN KEY (created_by) REFERENCES portal_members(id) ON DELETE CASCADE\n);\n\nCREATE TABLE IF NOT EXISTS portal_budget_entries (\n  id TEXT PRIMARY KEY,\n  account_id TEXT NOT NULL,\n  entry_type TEXT NOT NULL\n    CHECK (entry_type IN ('income','expense','commitment')),\n  category TEXT NOT NULL DEFAULT 'general',\n  amount_minor INTEGER NOT NULL CHECK (amount_minor >= 0),\n  description TEXT NOT NULL,\n  occurred_at TEXT NOT NULL,\n  team_code TEXT,\n  project_slug TEXT,\n  status TEXT NOT NULL DEFAULT 'pending'\n    CHECK (status IN ('pending','approved','rejected')),\n  created_by TEXT NOT NULL,\n  approved_by TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (account_id) REFERENCES portal_budget_accounts(id) ON DELETE CASCADE,\n  FOREIGN KEY (created_by) REFERENCES portal_members(id) ON DELETE CASCADE,\n  FOREIGN KEY (approved_by) REFERENCES portal_members(id) ON DELETE SET NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_meetings_start ON portal_meetings(starts_at,status);\nCREATE INDEX IF NOT EXISTS idx_meeting_participant ON portal_meeting_participants(member_id,meeting_id);\nCREATE INDEX IF NOT EXISTS idx_meeting_notes ON portal_meeting_notes(meeting_id,created_at);\nCREATE INDEX IF NOT EXISTS idx_polls_status ON portal_polls(status,created_at);\nCREATE INDEX IF NOT EXISTS idx_poll_votes ON portal_poll_votes(poll_id,option_id);\nCREATE INDEX IF NOT EXISTS idx_budget_entries_account ON portal_budget_entries(account_id,occurred_at);\nCREATE INDEX IF NOT EXISTS idx_budget_entries_status ON portal_budget_entries(status,created_at);\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_collaboration_finance_schema',\n  '{\"version\":\"2026.09-v12-collab-finance\",\"features\":[\"meeting-spaces\",\"meeting-calendar\",\"meeting-decisions\",\"meeting-reports\",\"polls\",\"poll-notifications\",\"budget-ledger\",\"budget-allocations\",\"budget-approvals\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0013_authority_cleanup.sql
export const PORTAL_V13_SQL = "-- CORE Portal V13 authority cleanup\n-- Backfill legacy member teams into the authoritative membership table.\n-- portal_members.teams_json remains for compatibility reads only and is no longer mutated.\n\nINSERT OR IGNORE INTO portal_team_memberships\n  (team_code,member_id,team_role,status,capabilities_json)\nSELECT\n  UPPER(TRIM(j.value)) AS team_code,\n  m.id,\n  CASE WHEN m.role='lead' THEN 'lead' ELSE 'engineer' END,\n  'active',\n  '[]'\nFROM portal_members m\nJOIN json_each(COALESCE(NULLIF(m.teams_json,''),'[]')) j\nJOIN portal_teams t ON t.code=UPPER(TRIM(j.value))\nWHERE json_valid(COALESCE(NULLIF(m.teams_json,''),'[]'))\n  AND TRIM(j.value)!='';\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_authority_schema',\n  '{\"version\":\"2026.09-v13\",\"membership_source\":\"portal_team_memberships\",\"native_repository_source\":\"portal_native_repositories\",\"legacy_teams_json\":\"compatibility-only\",\"legacy_portal_repositories\":\"external-catalog-only\"}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";
// migrations/0014_meeting_realtime.sql
export const PORTAL_V14_SQL = "-- CORE Portal V14 Meeting Realtime\n-- Maps portal meetings to managed Cloudflare RealtimeKit meeting IDs.\n\nCREATE TABLE IF NOT EXISTS portal_meeting_transports (\n  meeting_id TEXT PRIMARY KEY,\n  provider TEXT NOT NULL,\n  provider_meeting_id TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (meeting_id) REFERENCES portal_meetings(id) ON DELETE CASCADE\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_meeting_transport_provider\n  ON portal_meeting_transports(provider,provider_meeting_id);\n\nINSERT INTO site_settings (setting_key,value_json,updated_at)\nVALUES (\n  'portal_meeting_realtime_schema',\n  '{\"version\":\"2026.09-v14-meeting-realtime\",\"provider\":\"cloudflare-realtimekit\",\"features\":[\"audio-video\",\"audio\",\"screen-share\",\"participant-auth\",\"managed-sfu\"]}',\n  CURRENT_TIMESTAMP\n)\nON CONFLICT(setting_key) DO UPDATE SET\n  value_json=excluded.value_json,\n  updated_at=CURRENT_TIMESTAMP;\n";

export const PORTAL_MIGRATION_SQL = [PORTAL_SCHEMA_SQL,PORTAL_V2_SQL,PORTAL_V4_SQL,PORTAL_V5_SQL,PORTAL_V6_SQL,PORTAL_V7_SQL,PORTAL_V8_SQL,PORTAL_V9_SQL,PORTAL_V10_SQL,PORTAL_V11_SQL,PORTAL_V12_SQL,PORTAL_V13_SQL,PORTAL_V14_SQL].join("\n");
